return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Mine pluginate otsingusse','Activate %s' => 'Aktiveeri %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> nõuab <strong>%2$s</strong> paigaldamist ja aktiveerimist. <a href="%4$s">%3$s</a>','Enter your code here' => 'Sisestage oma kood siia','Add %s' => 'Lisa %s','Remove' => 'Eemaldage','Order number and receipt will be sent to this email address.' => 'Tellimuse number ja kviitung saadetakse sellele e-posti aadressile.','Apartment, unit, building, floor, etc.' => 'Korter, üksus, hoone, korrus jne.','Shipping phone' => 'Laevatelefon','Only used for shipping-related questions.' => 'Kasutatakse ainult saatmisega seotud küsimuste puhul.','Single step' => 'Üks samm','Click to go to the order summary' => 'Klõpsake, et minna tellimuse kokkuvõttesse','Cart total:' => 'Korvi kokku:','Proceed to %s' => 'Edasi %s','Proceed to contact' => 'Võtke ühendust','Proceed to shipping' => 'Jätkake saatmist','Proceed to billing' => 'Jätkake arveldamist','Proceed to payment' => 'Jätkake maksmisega','Shipping method' => 'Tarne meetod','Additional notes' => 'Täiendavad märkused','Payment method' => 'Makseviis','Step %1$s of %2$s' => 'Step %1$s of %2$s (samm %1$s of %2$s)','Change: %s' => 'Muudatus: %s','Not selected yet.' => 'Ei ole veel valitud.','Same as shipping address' => 'Sama kui tarneaadress','Same as billing address' => 'Sama mis arveldusaadress','Order summary' => 'Tellimuse kokkuvõte','Edit cart' => 'Muuda ostukorvi','Did you mean %s?' => 'Kas sa mõtlesid %s?','Change email address to: {suggestion-value}' => 'Muuda e-posti aadressi: {suggestion-value}','This is a required field.' => 'See on kohustuslik väli.','This is not a valid email address.' => 'See ei ole kehtiv e-posti aadress.','This field does not match the related field value.' => 'See väli ei vasta seotud välja väärtusele.','The CPF number "{cpf_number}" is invalid.' => 'CPF-number "{cpf_number}" on kehtetu.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ number "{cnpj_number}" on kehtetu.','(Required)' => '(Kohustuslik)','Checkout Header - Desktop' => 'Kassa päis - töölauaarvuti','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Näita vidinaid suurtel ekraanidel kassa päises. Kuvatakse ainult siis, kui kasutate pluginaga kassaprogrammi päistikku.','Checkout Header - Mobile' => 'Kassa päis - mobiilne','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Näita vidinaid mobiilseadmete jaoks kassade päise all. Kuvatakse ainult siis, kui kasutate pluginaga kassaprogrammi päistekülge.','Checkout Sidebar' => 'Kassas külgriba','Display widgets on the checkout sidebar after the order summary.' => 'Näita vidinaid kassas külgribal pärast tellimuse kokkuvõtet.','Checkout Order Summary' => 'Kassatellimuse kokkuvõte','Display widgets inside the order summary at the checkout page.' => 'Näita vidinaid tellimuse kokkuvõtte sees kassalehel.','Checkout Below Place Order' => 'Kassasse allpool Tee tellimus','Display widgets below the place order button at the checkout page.' => 'Näita vidinaid tellimuse esitamise nupu all kassalehel.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Näita vidinaid kassas jaluses. Kuvatakse ainult siis, kui kasutate plugina kassaplatvormi jalustikku.','Classic' => 'Klassikaline','Boxed' => 'Karbis','Split' => 'Jagatud','Minimalist' => 'Minimalistlik','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Fluid Checkout ja Delivery Date pluginad CodeRockz poolt','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Me tuvastasime, et kasutate CodeRockz\'i pistikprogramme Delivery & Pickup Date Time for WooCommerce (tasuta ja PRO). Integratsioon nende pistikprogrammidega on viidud üle Fluid Checkout PRO-sse.</p>','Upgrade to PRO' => 'Uuendage PRO-ks','Fluid Checkout database updated successfully' => 'Fluid Checkout andmebaasi uuendati edukalt','The database changes where applied successfully.' => 'Andmebaasi muudatused rakendati edukalt.','Dismiss' => 'Lase lahti','Fluid Checkout database update' => 'Fluid Checkout andmebaasi uuendamine','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Andmebaasis on vaja teha mõningaid muudatusi. Nagu iga uuenduse puhul, soovitame teil <strong>teha oma veebisaidi täielik varukoopia enne jätkamist</strong>.','Update database' => 'Andmebaasi ajakohastamine','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout ei ühildu Divi Builderi kassade paigutusega','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout vajab töötamiseks klassikalist WooCommerce\'i lühikoodipõhist kassavormi. Kui kasutate Divi Builderit kassalehe välimuse kohandamiseks, asendatakse klassikalised lühikoodid Divi Builderi kohandatud vidinatega iga kassalehe osa jaoks. Need kohandatud vidinad ei ühildu Fluid Checkout\'iga.</p><p>Pöörake oma kassalehte, asendades Divi Builderi vidinad teksti vidinaga, mis sisaldab lühikoodi <code>[woocommerce_checkout]</code>.</p>','Edit the checkout page' => 'Kassalehe muutmine','Read the documentation.' => 'Lugege dokumentatsiooni.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Germanized PRO mitmeastmelise kassasüsteemi funktsioon tuleb Fluid Checkout\'i kasutamisel välja lülitada.','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkout\'i kasutamisel muutub Germanized PRO pluginast pärit mitmeastmeline funktsioon tarbetuks ja võib põhjustada <strong>kriitilisi vigu uute tellimuste töötlemisel</strong>. Palun lülitage Germanized PRO mitmeastmelise kassaprogrammi funktsioon pluginate seadetes välja.','Go to Germanized settings' => 'Mine saksakeelsete seadete juurde','Thanks for choosing Fluid Checkout!' => 'Täname, et valisid Fluid Checkout\'i!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Te olete pluginat juba mõnda aega kasutanud. Kuidas sulle seni meeldib? <br>Palun anna meile kiire hinnang, me hindame iga tagasisidet ja see julgustab meid pluginat pidevalt täiustama :)','Rate the plugin' => 'Hinda pluginat','I need help!' => 'Ma vajan abi!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Mõned funktsioonid WooCommerce Checkout Manager by Quadlayers ei pruugi töötada ootuspäraselt, kui seda kasutatakse koos Fluid Checkoutiga. Loe <a href="%s">Meie dokumentatsiooni</a> lisateavet ja alternatiivseid lahendusi.','Read documentation' => 'Dokumentatsiooni lugemine','Don\'t show this again' => 'Ära näita seda enam','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Rohkem disainimalle','Optimized cart page' => 'Optimeeritud ostukorvi lehekülg','Optimized order received / thank you page' => 'Optimeeritud tellimuse saamise / tänuleht','Edit cart contents at checkout page' => 'Muuda ostukorvi sisu kassalehel','Account matching / user matching' => 'Konto sobitamine / kasutaja sobitamine','Trust symbols on the cart and thank you pages' => 'Usaldussümbolid ostukorvis ja tänu lehekülgedel','More positions for the coupon code on the checkout page' => 'Rohkem positsioone kupongi kood kassaleheküljel','International phone numbers' => 'Rahvusvahelised telefoninumbrid','Gift messages and packing slips' => 'Kinkesõnumid ja pakkelehti','Local pickup and in-store collection' => 'Kohaliku kättesaamise ja kohapealse kogumise võimalus','EU-VAT Assistant' => 'ELi käibemaksu assistent','I already have it – Hide this offer' => 'Mul on see juba olemas - Peida see pakkumine','Activated' => 'Aktiveeritud','Address book' => 'Aadressiraamat','Select an image' => 'Valige pilt','Cart layout' => 'Ostukorvi paigutus','Cart optimizations' => 'Ostukorvi optimeerimine','Enable cart page optimizations' => 'Võimaldage ostukorvilehe optimeerimine','Header and footer template' => 'Pea- ja jaluslehe mall','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Kontrollib, kas kasutada häireteta lehe päise- ja jaluslehte või säilitada hetkel aktiivse teema päise- ja jaluslehte.','Distraction free header and footer' => 'Tähelepanuvaba päis ja joonealune osa','Theme\'s header and footer' => 'Teema päis ja alumine osa','Cart elements' => 'Ostukorvi elemendid','Make the order summary stay visible on the cart page while scrolling' => 'Teha tellimuse kokkuvõte nähtavaks ostukorvilehel kerimise ajal','Coupon codes' => 'Kupongi koodid','Hidden' => 'Peidetud','Before the cart items section' => 'Enne ostukorvipunktide sektsiooni','Inside the cart items section' => 'Korvi esemete sektsiooni sees','After the cart items section' => 'Pärast ostukorvipunktide sektsiooni','Before the shipping section' => 'Enne laevanduse osa','After the shipping section' => 'Pärast laevanduse osa','Before the order summary' => 'Enne tellimuse kokkuvõtet','Inside the order summary' => 'Tellimuse kokkuvõte','Before the order totals' => 'Enne tellimuse kogusummat','After the order totals' => 'Pärast tellimuse kogusummat','After the order summary' => 'Pärast tellimuse kokkuvõtet','Shipping' => 'Laevandus','Select position where to display the shipping costs and calculator on the cart page.' => 'Valige positsioon, kus kuvatakse saatmiskulud ja kalkulaator ostukorvilehel.','Display as a cart section' => 'Näita kui ostukorvi sektsiooni','Cross-sells' => 'Ristmüük','Select position where to display the cross-sells section on the cart page.' => 'Valige positsioon, kus kuvatakse ristmüügi sektsioon ostukorvilehel.','Before the cart actions' => 'Enne käru toiminguid','After the cart actions' => 'Pärast ostukorviga seotud tegevusi','Layout of cross-sell items on the cart page.' => 'Ristmüügiartiklite paigutus ostukorvilehel.','Optimized horizontal cross-sells layout' => 'Optimeeritud horisontaalne ristmüükide paigutus','Theme\'s cross-sells layout' => 'Teema ristmüükide paigutus','Number of cross-sell items to display on the cart page' => 'Ostukorvi lehel kuvatavate ristmüügiartiklite arv','Add widget areas to the cart page' => 'Lisage ostukorvilehel vidinate alad','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Neid vidinaid kasutatakse usaldussümbolite ja usaldusmärkide lisamiseks ostukorvilehele.','Checkout' => 'Kassa','Checkout layout' => 'Kassa paigutus','Design template' => 'Disaini mall','Dark mode' => 'Tume režiim','Enable dark mode' => 'Tume režiimi sisselülitamine','Logo image' => 'Logo pilt','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Valige pilt, mida kuvatakse kassalehe päises. Kehtib ainult siis, kui kasutate häireteta päise- ja jaluslehte.','Header background color' => 'Pealkirja taustavärv','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Valige kassalehe päise taustavärv. Kehtib ainult siis, kui kasutate häireteta päise ja jaluseadet.','HTML color value. ie: #f3f3f3' => 'HTML-värvi väärtus. st: #f3f3f3','Page background color' => 'Lehe taustavärv','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Valige kassalehe taustavärv. Värvi rakendatakse <em>body</em> elemendile.','Footer background color' => 'Alumise osa taustavärv','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Valige kassalehe alumise osa taustavärv. Kehtib ainult siis, kui kasutate häireteta päise ja jaluslehe.','Progress bar' => 'Progress bar','Display the checkout progress bar when using multi-step checkout layout' => 'Näidata kassasõidu eduriba, kui kasutate mitmeastmelise kassasõidu kujundust','Make the checkout progress bar stay visible while scrolling' => 'Teha kassas progressiriba nähtavaks kerimise ajal','Express checkout' => 'Express kassasüsteem','Enable the express checkout section' => 'Võta kasutusele kiirkassa sektsioon','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Kuvab kassas kiirkassa sektsiooni, kui toetatud makseväravadel on see funktsioon lubatud.','Display express checkout buttons in one line for larger screens' => 'Ekspresskassanuppude kuvamine ühes reas suuremate ekraanide jaoks','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ignoreeri täiendavaid nõutavaid välju, kui maksad ühilduva Express Checkout maksevärava abil.','Make the order summary stay visible while scrolling' => 'Teha tellimuse kokkuvõte nähtavaks kerimise ajal','Choose a background color for the order summary section.' => 'Valige tellimuse kokkuvõtte sektsiooni taustavärv.','Highlight the order totals row in the order summary table' => 'Märkige tellimuse kokkuvõtte tabelis tellimuse kogusummade rida.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Kõige kasulikum, kui tellimuse kokkuvõtte sektsioonil ei ole esile tõstetud taustavärvi. Võiks ka ostukorv, saadud tellimus ja tellimuse vaatamise lehtedel, kui kasutate Fluid Checkout PRO-d.','Action link on the order summary at checkout.' => 'Tegevuse link tellimuse kokkuvõttes kassas.','Edit cart link' => 'Muuda ostukorvi linki','Cart items count' => 'Ostukorvi esemete arv','Link to shop page' => 'Link poe lehele','Cart items' => 'Ostukorvi esemed','Hide cart items errors at the checkout page' => 'Varjata ostukorvis olevad vead kassalehel','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Ärge kuvage ostukorviga seotud veateadet kassalehe ülaosas. Ostu lõpetamiseks kassavormi esitamisel kuvatakse need veateated alati.','Place order' => 'Tee tellimus','Define the position to display "Place order" and terms checkbox section.' => 'Määrake positsioon, kus kuvatakse "Tellimus" ja tingimuste märkeruutude sektsioon.','Some options might not be compatible with some plugins and themes.' => 'Mõned valikud ei pruugi ühilduda mõne pistikprogrammi ja teemaga.','Below the payment section' => 'Maksmise sektsiooni all','Below the order summary' => 'Allpool on esitatud tellimuse kokkuvõte','Both below the payment section and the order summary' => 'Nii makseosa kui ka tellimuse kokkuvõtte all','Add widget areas to the checkout page' => 'Lisage kassalehe vidinaid','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Neid vidinaid kasutatakse usaldussümbolite ja usaldusmärkide lisamiseks kassaleheküljele.','Display the coupon codes section title' => 'Kuvada kupongikoodide jaotise pealkiri','Select position where to display the coupon codes section on the checkout page.' => 'Valige positsioon, kus kuvada kupongikoodide sektsioon kassalehel.','Before the checkout steps' => 'Enne kassasammude tegemist','As a substep before payment methods' => 'Makseviisidele eelneva alamtegevusena','As a substep after payment methods' => 'Makseviiside järgse alljärgnevusena','Default button style' => 'Vaikimisi nupu stiil','"Add" link button' => '"Lisa" lingi nupp','Checkout fields' => 'Kassaväljad','Optional fields' => 'Vabatahtlikud väljad','Hide optional fields behind a link button' => 'Peida valikulised väljad lingi nupu taha','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Soovitatav on jätta see valik märgitud, et vähendada avatud sisendväljade arvu, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">loe uuringut</a>.','Do not hide "Address line 2" fields behind a link button' => 'Ärge peitke "Aadressirea 2" väljad lingi nupu taha.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Soovitatav ainult siis, kui enamik kliente vajab tegelikult välja "Aadressi rida 2" või kui õige tarneaadressi saamine on väga oluline (nt toiduainete ja muude kergesti riknevate toodete tarnimisel).','Billing address' => 'Arve esitamise aadress','Select position where to display the billing address section on the checkout page.' => 'Valige positsioon, kus kuvatakse arveldusaadressi osa kassalehel.','As a step before shipping' => 'Enne laevanduse alustamist','As a sub-step before the shipping address section' => 'Alametapina enne tarneaadressi osa','As a sub-step after the shipping address section' => 'Alametapina pärast tarneaadressi osa','As a step after shipping' => 'Sammuna pärast saatmist','As a sub-step before the payment section' => 'Alametapina enne makseosa','Force billing and shipping addresses to the same (single section)' => 'Sundida arveldus- ja tarneaadressid samaks (üks osa)','Checkbox for "Same as shipping/billing address" checked by default' => 'Vaikimisi on märgitud ruut "Sama kui tarne-/arveaadress".','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Valikukast "Sama kui saatmisaadress" hakkab vaikimisi olema märgitud, kui tarneaadressi osa kuvatakse esimesena. <br>Kast "Sama kui arveldusaadress" hakkab vaikimisi olema märgitud, kui arveldusaadressi osa kuvatakse esimesena. <br> Soovitatav on jätta see valik märgitud, kuna see vähendab oluliselt avatud sisendväljade arvu kassas, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">lugege uuringut</a>.','Highlight the billing address section in the checkout form' => 'Märkige kassavormi arveldusaadressi sektsioon','Shipping address' => 'Tarneaadress','Highlight the shipping address section in the checkout form' => 'Tõsta esile saatmisaadressi osa kassavormil','Shipping methods' => 'Laevandusmeetodid','Choose in which position to display the shipping methods section.' => 'Valige, millises positsioonis kuvatakse saatmisviiside osa.','Before shipping address' => 'Enne saatmise aadressi','After shipping address' => 'Pärast saatmisaadressi','Local pickup' => 'Kohalik pealevõtmine','Removes shipping address section when a local pickup shipping method is selected.' => 'Eemaldab tarneaadressi osa, kui on valitud kohalik tarneviis.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Asendab tarneaadressi pealevõtmiskoha asukohaga, kui on valitud kohalik pealevõtmise tarneviis.','Choose which address to save as the shipping address for local pickup orders.' => 'Valige, millise aadressi soovite salvestada kohalikuks tarneaadressiks tellimuste puhul.','Save the selected pickup location' => 'Salvesta valitud pealevõtmiskoht','Save same as the billing address' => 'Salvesta sama, mis arveldusaadress','Do not save any shipping address' => 'Ärge salvestage ühtegi tarneaadressi','Company name field for shipping address' => 'Ettevõtte nime väli tarneaadressi jaoks','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Muuda ettevõtte nime väljale nähtavust saatmisaadressi sektsioonis kassavormil.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Kui väljale on määratud "vabatahtlik", mis on vaikimisi nähtavuse olek, ei rakendata mingeid muudatusi, et teised pistikprogrammid saaksid rakendada vajalikke muudatusi.','Hidden (remove field)' => 'Peidetud (eemalda väli)','Optional' => 'Valikuline','Required' => 'Nõutav','Add shipping phone field to the checkout form.' => 'Lisage kassavormile saatetelefoni väli.','Choose in which step to display the shipping phone field.' => 'Valige, millises etapis kuvatakse saatetelefoni väli.','Contact step' => 'Kontakt samm','Billing phone' => 'Arveldustelefon','Add billing phone field to the checkout form.' => 'Lisage arveldustelefoni väli kassavormi.','Choose in which step to display the billing phone field.' => 'Valige, millises etapis kuvatakse arveldustelefoni väli.','Show country code beside the flag' => 'Näita riigi koodi lipu kõrval','Show an example of a valid phone number inside phone fields' => 'Näita näide kehtiva telefoninumbri kohta telefoniväljade sees','Do not change placeholders' => 'Ärge muutke paigutussätteid','Show if not defined' => 'Näita, kui ei ole määratletud','Always show' => 'Näita alati','Order notes' => 'Tellimuse märkmed','Define the visibility of the additional order notes field.' => 'Määrake täiendavate tellimuse märkuste välja nähtavus.','Gift options' => 'Kinkimisvõimalused','Allow customers to add a gift message and other gift related options to the order.' => 'Võimaldage klientidel lisada tellimusele kinkesõnum ja muid kingitusega seotud võimalusi.','Display the gift message as part of the order details table instead of a separate section' => 'Kuvada kingitusteade eraldi jaotise asemel tellimuse üksikasjade tabeli osana.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'See valik mõjutab tellimuse kinnituse lehte (tänu lehekülg) ja tellimuse üksikasju kontolehtedel, e-kirjades ja saatelehtedel.','Account matching' => 'Konto sobitamine','Enable the account matching feature' => 'Võta kasutusele konto sobitamise funktsioon','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Seostage külaliskliendi tellimused tema olemasoleva kontoga, kui kliendi kontaktandmetega konto on juba olemas.','Display message when an account exists with the email address provided' => 'Kuvatakse teade, kui konto on esitatud e-posti aadressiga olemas.','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Asendab konto loomise väljad teatega ja sisselogimise võimalusega. Mõnes kontekstis võib olla soovitatav jätta see valik välja lülitatud, et kaitsta klientide privaatsust.','Dashboard' => 'Armatuurlaud','Integrations' => 'Integratsioonid','License keys' => 'Litsentsivõtmed','Visit our website for more information about our plugins and add-ons.' => 'Külastage meie veebisaiti, et saada lisateavet meie pluginate ja lisandmoodulite kohta.','Order pay page' => 'Telli makse lehekülg','Order pay' => 'Tellimuse tasu','Enable order pay page optimizations' => 'Tellimuse tasulise lehe optimeerimise võimaldamine','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Muudab tellimuse maksmise lehe kujundust olemasolevate tellimuste puhul, mis ootavad kliendi makseid.','Add widget areas to the order pay page' => 'Lisa vidinaid tellimuse maksmise lehele','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Neid vidinaid kasutatakse usaldussümbolite ja usaldusmärkide lisamiseks tellimuse tasumise lehele.','Thank you page & order details layout' => 'Tänuslehe ja tellimuse üksikasjade kujundus','Order details optimizations' => 'Tellimuse üksikasjade optimeerimine','Enable thank you page and order details optimizations' => 'Võimaldage tänu lehekülje ja tellimuse üksikasjade optimeerimine','Changes the layout of order details on the thank you page and account pages.' => 'Muudab tellimuse üksikasjade paigutust tänulehel ja kontolehel.','Enable order details customizations on email notifications' => 'Tellimuse üksikasjade kohandamise võimaldamine e-posti teadetes','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Uute jaotiste kuvamine ja jaotiste järjekorra muutmine e-posti teadetes. Tellimuse üksikasjade stiilid e-posti teadetes jäävad muutumatuks.','Thank you page' => 'Aitäh lehekülg','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Need valikud mõjutavad tänu lehekülge, mida tuntakse ka kui tellimuse saamise või tellimuse kinnitamise lehekülgi.','Order details layout' => 'Tellimuse üksikasjade paigutus','Display the order details with wide layout on the thank you page' => 'Tellimuse üksikasjade kuvamine laia paigutusega tänulehel','Add widget areas to the thank you page' => 'Lisage tänulehele vidinaid','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Neid vidinaid kasutatakse usaldussümbolite ja usaldusmärkide lisamiseks tänulehele.','Order actions' => 'Tellimusmeetmed','Choose in which position to display the order actions.' => 'Valige, millises asendis tellimuse toimingud kuvatakse.','Inside the order overview' => 'Tellimuse sisemine ülevaade','After the order overview' => 'Pärast tellimuse ülevaadet','After order sections' => 'Pärast tellimuse jaotisi','Order status' => 'Tellimuse staatus','Display the order status progress bar' => 'Tellimuse staatuse eduriba kuvamine','Choose in which position to display the section.' => 'Valige, millises asendis lõik kuvatakse.','After the order overview and payment instructions' => 'Pärast tellimuse ülevaadet ja maksejuhiseid','Before the order items section' => 'Enne tellimusartiklite osa','Inside the order items section' => 'Tellimuse esemete sektsioonis','After the order items section' => 'Pärast tellimusartiklite osa','On the sidebar' => 'Külgribal','Order downloads' => 'Tellige allalaadimisi','Gift message' => 'Kinkesõnum','Tools' => 'Tööriistad','Troubleshooting' => 'Veaotsing','Debug options' => 'Vigade kõrvaldamise valikud','Debug mode' => 'Kõrvaldamisrežiim','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Debugimisrežiimi kasutamine mõjutab veebisaidi jõudlust. Kasutage seda valikut ainult tõrkeotsingu ajal.','Load unminified assets' => 'Laadige minimeerimata varasid','Enhanced select fields' => 'Täiustatud valitud väljad','Fix automatic zoom-in on form fields' => 'Fikseeri automaatne sisse suumimine vormiväljadel','Set <code>font-size</code> inside form fields to 16px' => 'Määra <code>font-size</code> vormiväljade sees 16px-le','Fluid Checkout' => 'Vedelikukontroll','Settings' => 'Seaded','Support' => 'Toetus','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Upgradeeri PRO</a>, et avada rohkem võimalusi.','(PRO)' => '(PRO)','(experimental)' => '(eksperimentaalne)','Please verify your phone number.' => 'Palun kontrollige oma telefoninumbrit.','The Bluehost Plugin' => 'Bluehost Plugin','Custom fields' => 'Kohandatud väljad','Enable custom shipping email field' => 'Lubage kohandatud saatmise e-posti väli','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Kui see on lubatud, lisatakse Bluehosti pluginast saadetise e-posti väli kassavormile.','Captcha Pro by BestWebSoft' => 'Captcha Pro by BestWebSoft','Captcha position' => 'Captcha positsioon','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Määrake positsioon, kus kuvatakse captcha osa. Mõned positsioonid ei pruugi toimida sõltuvalt valitud captcha tüübist.','Selecting a pickup point is required before proceeding.' => 'Enne jätkamist on vaja valida ülesvõtmiskoht.','Pickup point' => 'Ülevõtmise koht','Pickup point not selected yet.' => 'Ülevõtmiskoht ei ole veel valitud.','Pickup point:' => 'Ülestõstmise koht:','Mailchimp for WooCommerce' => 'Mailchimp WooCommerce jaoks','Subscribe checkbox' => 'Telli märkeruut','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Lülita tellimise märkeruudu positsioon kassalehel ümber ja näita see alati kontakti sammul.','Before Shipping Address' => 'Enne saatmise aadressi','(originally "%s")' => '(algselt "%s")','After Shipping Address' => 'Pärast tarneaadressi','Selecting a collection point is required when shipping with FermoPoint.' => 'FermoPointiga saatmisel on vaja valida kogumispunkt.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Kui see on kontrollitud, teavitab kasutajatele saadetud e-kirjas kirjavigadest. (See funktsioon on välja lülitatud, sest Fluid Checkout pakub seda funktsiooni. Selle valiku muutmine ei jõustu)','Enable Mail Check: (disabled feature)' => 'Maili kontrolli lubamine: (keelatud funktsioon)','Carrier:' => 'Kandjaks:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce e-posti turundus','Sign up checkbox position' => 'Registreeru märkeruutu positsioon','Move the sign up checkbox to the contact step' => 'Liigutage registreerimise märkeruut kontakti sammule','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Kui see on lubatud, viiakse märkeruut kontakti sammu, sõltumata Sendinblue\'i lisaseadetes määratud kuvamiskohast.','Theme Betheme' => 'Teema Betheme','Checkout progress' => 'Kassa edenemine','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Väljastada Betheme\'i kassasammude osa kassas, ostukorvis ja saadud tellimuse lehekülgedel.','Theme Fennik' => 'Teema Fennik','Breadcrumbs' => 'Leivapuru','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Fennik-teemast leivakriipsude sektsiooni väljastamine, kui kasutate Fluid Checkouti päise ja jalusfaili.','Theme Go' => 'Teema Go','My account layout' => 'Minu konto kujundus','Enable wide layout on "My account" page.' => 'Lubage lai paigutus lehel "Minu konto".','Theme Impreza' => 'Teema Impreza','Header' => 'Pealkiri','Spacing for site header at the checkout page (in pixels)' => 'Saidi päise vahekaugus kassalehel (pikslites)','Only applicable when using the Impreza theme header at the checkout page.' => 'Kohaldatakse ainult siis, kui kasutate Impreza teema pealkirja kassalehel.','Theme Kapee' => 'Teema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Kapee teema kassasammude osa väljastamine kassas, ostukorvis ja saadud tellimuse lehekülgedel.','Theme Porto' => 'Teema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Väljastage Porto teema kassasammude osa kassasse, ostukorvi ja saadud tellimuse lehekülgedel.','Theme Pressmart' => 'Teema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Pressmart-teema kassasammude osa väljastamine kassas, ostukorvis ja saadud tellimuse lehekülgedel.','Theme The Gem' => 'Teema Kalliskivi','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Väljastada kassasammude osa The Gem teemast, kui kasutate Fluid Checkout päise ja jalusesse.','Theme Woodmart' => 'Teema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Väljastada kassasammude sektsioon Woodmart teemast, kui kasutate Fluid Checkout päise ja jalusesse.','Checkout options' => 'Kassasüsteemi valikud','Disable the theme checkout options' => 'Lülita teema kassasse valikud välja','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Valikud kuvada toote pilti, koguse väli, eemaldamisnupp ja teema poolt lisatud link toote lehele on vaikimisi välja lülitatud.','Theme Atomion' => 'Teema Atomion','Order progress' => 'Tellimuse edenemine','Display order progress from the theme' => 'Näita tellimuse edenemist teemast','Display the form field labels visible on the page' => 'Kuvada vormiväljade sildid lehel nähtavad','It is recommended to keep this option enabled for a better user experience.' => 'Parema kasutajakogemuse tagamiseks on soovitatav see valik sisse lülitada.','Theme ZK Nito' => 'Teema ZK Nito','Add extra fields to the checkout form' => 'Lisage kassavormi lisaväljad','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Lisab tarneaadressi sektsiooni täiendava saatmise e-posti ja saatmise telefoni välja.','Go to the home page' => 'Mine kodulehele','Skip to content' => 'Skip to content','Create an account' => 'Konto loomine','Log in to your account' => 'Logi oma kontole sisse','Already have an account?' => 'Kas teil on juba konto?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Sisselogitud kui %1$s. <a href="%2$s">Logi välja</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Teie tellimuse kogusumma on %s. Rohkem makseid ei ole vaja teha.','Close and continue with checkout' => 'Sulge ja jätka kassaga','Continue' => 'Jätka','Parcel terminal' => 'Pakiautomaat','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>See vidin on asendatud Fluid Checkoutiga. </p><p>Kasutades Fluid Checkout\'i, peab kassaleht kasutama originaalset WooCommerce\'i lühikoodi <code>[woocommerce_checkout]</code>, et see töötaks korralikult.</p><p>Lisainformatsiooni saamiseks külastage Fluid Checkout\'i dokumentatsiooni.</p>','Theme The7' => 'Teema The7','Additional header sections' => 'Täiendavad pealkirjaosad','Output additional header sections if enabled in the theme settings.' => 'Täiendavate päislõikude väljastamine, kui see on teema seadetes lubatud.','More information' => 'Lisateave','Pick a Locker' => 'Vali kapis','Page template' => 'Lehekülje mall','Use `Order confirmation` page template for block-based themes' => 'Kasutage "Tellimuse kinnituse" lehekülje malli plokipõhiste teemade jaoks','Only applies when using a block-based theme.' => 'Kehtib ainult siis, kui kasutatakse plokipõhist teemat.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Maksevorm','Apply styles to the Stripe payment form fields' => 'Stiilide rakendamine Stripe\'i maksevormi väljadele','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Kui see on lubatud, rakendab Fluid Checkout pluginaga ühildumiseks optimeeritud stiile. Kui kasutate Stripe\'i maksevormi väljade jaoks kohandatud stiile, võite selle välja lülitada.','Theme Nyture' => 'Teema Nüüdure','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Väljastage nüüdure teema kassasammude osa, kui kasutate Fluid Checkouti.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Võimaldab klientidel teha makseid tellimuste eest, mis on kas poe administraatori poolt käsitsi loodud või mida ei ole kassas lõpule viidud.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayersi plugin WooCommerce Checkout Manager ei ühildu Fluid Checkoutiga','Company name field for billing address' => 'Ettevõtte nime väli arveldusaadressi jaoks','Change visibility for the company name field for the billing address section on the checkout form.' => 'Muuda ettevõtte nime välja nähtavust arveldusaadressi sektsioonis kassavormil.','Theme Bookshelf' => 'Teema raamaturiiul','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Väljastada kassasammude sektsioon Bookshelfi teemast, kui kasutate Fluid Checkouti.','Account password' => 'Konto parool','An account will be created with the information provided at checkout when completing the order.' => 'Konto luuakse tellimuse täitmisel kassas esitatud andmete alusel.','Choose the style of the progress bar.' => 'Valige eduriba stiil.','Bars' => 'Baarid','Theme Ireca' => 'Teema Ireca','WooCommerce page layout' => 'WooCommerce lehe kujundus','Force wide layout on WooCommerce pages' => 'Force lai paigutus WooCommerce lehekülgedel','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'See tagab, et WooCommerce\'i lehekülgedel, sealhulgas kassas, ostukorvis, saadud tellimuse, tellimuse tasumise ja konto lehekülgedel ei ole sisuosa liiga kitsas.','WooCommerce Smart Coupons' => 'WooCommerce Smart Kupongid','Position on checkout page' => 'Asukoht kassalehel','Choose where to display the available coupons section on the checkout page.' => 'Valige, kus kuvada saadaval olevate kupongide osa kassalehel.','Before the progress bar' => 'Enne eduriba','After the progress bar' => 'Pärast eduriba','Before coupon codes section' => 'Enne kupongikoodide sektsiooni','Format phone numbers according to the rules for each country.' => 'Vormindage telefoninumbrid vastavalt iga riigi eeskirjadele.','Use precise phone number validation' => 'Kasutage täpset telefoninumbri valideerimist','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'See on eksperimentaalne funktsioon ja ei pruugi kõigis seadistustes toimida ootuspäraselt. Kasutage seda ettevaatlikult.','Phone number validation types used when precise validation is enabled.' => 'Telefoninumbri valideerimise tüübid, mida kasutatakse, kui täpne valideerimine on lubatud.','Mobile' => 'Mobiilne','Fixed line' => 'Fikseeritud liin','Toll free' => 'Tasuta','Or' => 'Või','Contact' => 'Kontakt','Multi step' => 'Mitu sammu','2 columns' => '2 veergu','1 column' => '1 veerg','Before checkout steps' => 'Enne kassasse minekut sammud','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Kui kasutate <em>"1 veerg"</em> kassaplaani, on see valik alati seatud <em>"Enne kassasammu"</em> ja kehtib ka töölaua vaates.','Position for the extra order summary section on mobile.' => 'Asukoht täiendava tellimuse kokkuvõtte sektsiooni jaoks mobiilis.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Valik <em>"Saidi päises"</em> kehtib ainult siis, kui kasutate häireteta päise.','On the site header (requires distraction-free header)' => 'Saidi päises (nõuab häireteta päise)','Initial state for the expansible order summary section on mobile.' => 'Esialgne olek laiendatava tellimuse kokkuvõtte sektsiooni jaoks mobiilis.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Soovitame selle seadistada <em>laiendatud</em> järgmistele riikidele regulatiivsete nõuete tõttu: <strong>Saksamaa</strong>, <strong>Austria</strong>, <strong>Sveits</strong>, <strong>Holland</strong>, <strong>Poola</strong>, <strong>Belgia</strong> ja <strong>Frangimaa</strong>.','Collapsed' => 'Kokkuvarisemine','Expanded' => 'Laiendatud','Do not show' => 'Mitte näidata','yes' => 'jah','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Kui arveaadressi osa kuvatakse pärast tarneaadressi osa ja arveaadressi telefoninumbri väli on märgitud „kohustuslikuks“, võib tarneaadressi telefoninumbri väli muutuda kohustuslikuks. See on vajalik selleks, et tagada tarneaadressi kopeerimine arveaadressile, kui vastav valik on märgitud; vastasel juhul ei pruugi klient suuda ostukorvi vormi täita.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Arve telefoninumbri väli võib muutuda kohustuslikuks, kui arve aadressi osa kuvatakse enne tarneaadressi osa ja tarne telefoninumbri väli on määratud kohustuslikuks. See on vajalik selleks, et tagada tarneaadressi kopeerimine arve aadressile, kui see valik on märgitud; vastasel juhul ei pruugi klient suuda ostukorvi vormi täita.','Settings profiles' => 'Seadistusprofiilid','Settings profile' => 'Seadete profiil','You do not have permission to perform this action.' => 'Teil puudub õigus seda toimingut teha.','You do not have permission to activate plugins.' => 'Sul puudub õigus pistikprogramme aktiveerida.','Missing plugin.' => 'Puuduv pistikprogramm.','Plugin activated.' => 'Pistikprogramm on aktiveeritud.','The following changes will be applied:' => 'Rakendatakse järgmised muudatused:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Alates Fluid Checkout 5.0 versioonist salvestatakse seaded teistmoodi. Vanad seaded on endiselt andmebaasis säilitatud, et vajaduse korral oleks võimalik minna tagasi eelmistele versioonidele.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Teie pood on uute seadistustega töötanud umbes 2 nädalat, seega saite andmebaasis salvestatud vanad seadistused kustutada. Palun pange tähele, et kui peate pärast puhastamist minna tagasi pistikprogrammi eelmistele versioonidele, kasutab see kõigi seadistuste puhul vaikimisi väärtusi.','Fluid Checkout settings cleanup' => 'Fluid Checkout’i seadete puhastamine','Delete leftover options' => 'Kustuta järelejäänud valikud','Help us improve Fluid Checkout' => 'Aita meil Fluid Checkouti täiustada','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Jaga Fluid Checkoutiga anonüümseid veebikeskkonna aruandeid, et saada kiiremat tuge ning aidata meil parandada ühilduvust ja mõõta mõju. Aruanded ei sisalda kliendi-, kasutaja- ega tundlikke andmeid. Saad igal ajal menüü „Tööriistad” seadetest valida, milliseid andmeid jagatakse.','Enable site environment reports' => 'Luba veebisaidi keskkonna aruanded','Review settings' => 'Vaata seadeid','This preview has expired. Reload the admin page to start a new preview.' => 'Selle eelvaate kehtivusaeg on lõppenud. Laadige haldusleht uuesti, et alustada uut eelvaadet.','Preview expired' => 'Eelvaade on aegunud','Orders cannot be placed in the preview.' => 'Eelvaates ei ole võimalik tellimusi esitada.','Logging in is not available in the preview.' => 'Eelvaates ei ole sisselogimine võimalik.','Accounts cannot be created in the preview.' => 'Eelvaates ei ole võimalik kontosid luua.','Requests to other sites are blocked in the preview.' => 'Eelvaates on blokeeritud päringud teistele veebisaitidele.','Processing…' => 'Töötlemine…','Something went wrong. Please try again.' => 'Midagi läks valesti. Palun proovi uuesti.','Activate plugin' => 'Plugin aktiveerimine','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO – Täielik kassapakett','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Kõik PRO-funktsioonid + kõik lisamoodulid ühe hinnaga. Disainimallid, optimeeritud ostukorvi ja tellimuse kinnituse leheküljed, kontode ühendamine ja palju muud.','Optimized order pay page' => 'Optimeeritud tellimuse maksmise leht','Express checkout buttons from supported payment methods' => 'Toetatud makseviiside kiirmakse nupud','Delayed account creation' => 'Konto loomise viivitus','Address autocomplete with Google Maps APIs' => 'Aadressi automaatne täitmine Google Mapsi API-de abil','Multiple saved addresses with the address book' => 'Aadressiraamatusse salvestatud mitu aadressi','EU-VAT assistant' => 'ELi käibemaksu abimees','Hide this section' => 'Peida see osa','Learn more' => 'Lisateave','Get early access' => 'Hangi varajane juurdepääs','Activate add-on' => 'Lülita lisandmoodul sisse','Get more out of your checkout journey' => 'Saage oma ostukogemusest veelgi rohkem kasu','Test API key' => 'API-võtme testimine','Guided setup' => 'Juhendatud seadistamine','Options' => 'Valikud','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Määrake paigutus ja kujundus lehel <a href="%s">ostukorvi valikud</a>.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Luba külaliskassasse minek ja/või vaata <a href="%s">kliendikontode seadeid</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Luba optimeeritud <a href="%1$s">ostukorvi</a>, <a href="%2$s">tänulehe</a> ja <a href="%3$s">tellimuse maksmise</a> leheküljed.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Luba Google Mapsis <a href="%s">aadresside automaatne täiendamine</a>.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Luba mitme salvestatud aadressi kasutamine <a href="%s">aadressiraamatu</a> abil.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Kontrolli, kas sinu teema või muude paigaldatud pistikprogrammide jaoks on saadaval mingeid <a href="%s">integreerimisvõimalusi</a>.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Saate kiiremat tuge ning aitate meil parandada ühilduvust ja mõõta mõju. <a href="%s">Lülitage tööriistade seadetes sisse kasutamise jälgimine</a>.','Missing settings tab.' => 'Puudub vahekaart „Seaded”.','Getting started' => 'Esimesed sammud','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Suurepärane! Teie kassaleht töötab nüüd Fluid Checkouti platvormil.</strong> Siin on mõned sammud, millega alustada:','Completed' => 'Lõpetatud','Preview report data' => 'Aruande andmete eelvaade','Send now' => 'Saada kohe','Auto-detect' => 'Automaatne tuvastamine','Afrikaans' => 'afrikaani keel','Albanian' => 'Albaania','Amharic' => 'amhari keel','Arabic' => 'araabia keel','Armenian' => 'armeenia','Azerbaijani' => 'Aserbaidžaani','Basque' => 'baski','Belarusian' => 'valgevene','Bengali' => 'bengali keel','Bosnian' => 'bosnia','Bulgarian' => 'Bulgaaria','Burmese' => 'Birma','Catalan' => 'katalaani','Chinese' => 'hiina keel','Chinese (Simplified)' => 'Hiina (lihtsustatud)','Chinese (Hong Kong)' => 'Hiina (Hongkong)','Chinese (Traditional)' => 'Hiina keel (traditsiooniline)','Croatian' => 'horvaadi keel','Czech' => 'Tšehhi','Danish' => 'Taani','Dutch' => 'hollandi keel','English' => 'inglise keel','English (Australian)' => 'inglise keel (Austraalia)','English (Great Britain)' => 'inglise keel (Suurbritannia)','Estonian' => 'eesti keel','Farsi' => 'Farsi','Finnish' => 'soome keel','Filipino' => 'Filipiinlane','French' => 'prantsuse keel','French (Canadian)' => 'Prantsuse (Kanada)','Galician' => 'galiitsia keel','Georgian' => 'Gruusia','German' => 'Saksa keel','Greek' => 'kreeka','Gujarati' => 'gudžarati keel','Hebrew' => 'heebrea keel','Hindi' => 'hindi keel','Hungarian' => 'ungari keel','Icelandic' => 'islandi','Indonesian' => 'indoneesia keel','Italian' => 'itaalia keel','Japanese' => 'jaapani keel','Kannada' => 'Kannada','Kazakh' => 'Kasahhi','Khmer' => 'khmeeri keel','Korean' => 'Korea','Kyrgyz' => 'Kõrgõz','Lao' => 'Laos','Latvian' => 'Läti','Lithuanian' => 'Leedu','Macedonian' => 'Makedoonia','Malay' => 'malai keel','Malayalam' => 'malajalami keel','Marathi' => 'marathi keel','Mongolian' => 'mongoolia','Nepali' => 'nepaali keel','Norwegian' => 'norra keel','Polish' => 'Poola','Portuguese' => 'portugali keel','Portuguese (Brazil)' => 'portugali keel (Brasiilia)','Portuguese (Portugal)' => 'portugali keel (Portugal)','Punjabi' => 'pandžabi keel','Romanian' => 'Rumeenia','Russian' => 'vene','Serbian' => 'serbia','Sinhalese' => 'singali keel','Slovak' => 'Slovaki','Slovenian' => 'Sloveeni keel','Spanish' => 'hispaania keel','Spanish (Latin America)' => 'Hispaania keel (Ladina-Ameerika)','Swahili' => 'suahiili keel','Swedish' => 'Rootsi','Tamil' => 'tamili keel','Telugu' => 'telugu','Thai' => 'tai keel','Turkish' => 'Türgi','Ukrainian' => 'ukraina','Urdu' => 'urdu keel','Vietnamese' => 'vietnami keel','Zulu' => 'Zulu','Google address autocomplete' => 'Google’i aadresside automaatne täiendamine','Google Places API version' => 'Google Places API versioon','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Valige, millist Google Places API versiooni soovite kasutada. Soovitame minna üle uuele Places API-le niipea kui võimalik.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Soovitame kasutada „Places API (New)“, kuna alates 1. märtsist 2025 viib Google versiooni „Places API (Legacy)“ vananenud staatusesse, mis tähendab, et te ei saa seda teenust enam uute API-võtmete jaoks aktiveerida ning et see API-versioon ei ole lõpuks enam kättesaadav. Olemasolevad kontod, mis juba kasutavad vana API-d, võivad jätkata töötamist ilma häireteta.','(Recommended)' => '(Soovitatav)','Google API key' => 'Google’i API-võti','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Kopeeri oma Google API-võti ja kasuta testinuppu, et veenduda, et see toimib sellel veebisaidil. Veendu, et võti on kehtiv ja sinu domeenile lubatud, vastasel juhul võib aadressiväli blokeeruda, mis takistab klientidel tellimusi lõpule viimast.','Enable Google address autocomplete' => 'Luba Google’i aadresside automaatne täiendamine','Enable address autocompletion using the Google Maps APIs.' => 'Luba aadresside automaatne täiendamine Google Mapsi API-de abil.','Google API language' => 'Google API keel','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Seda keelt kasutatakse Google Places API aadressisoovituste kuvamiseks ning aadressid täidetakse automaatselt samuti selles keeles.','Result types' => 'Tulemustüübid','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Jäta tühjaks, et aktsepteerida mis tahes tüüpi tulemusi, mis annab tavaliselt paremaid vasteid. <a href="%s" target="_blank">Lisateavet leiad dokumentatsioonist</a>. <br>Vali kuni 5 tüüpi aadressiotsingu tulemusi, mida kuvatakse aadressi automaatse täitmise väljadel. <br>Külasta Google Mapsi dokumentatsiooni, et saada lisateavet <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">toetatud tüüpide kohta</a>.','Result types (Legacy API)' => 'Tulemustüübid (vanem API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Millist tüüpi aadressiotsingu tulemusi tuleks tagastada Places API (Legacy) kasutamisel. <br>Külasta vana Google Places API dokumentatsiooni, et saada lisateavet <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">toetatud tüüpide</a> kohta.','Company fields' => 'Ettevõtte valdkonnad','Enable autocomplete for the company name if available' => 'Luba ettevõtte nime automaatne täiendamine, kui see on võimalik','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Luba ettevõtte välja automaatne täitmine ettevõtte nime andmetega, kui need saadakse Google Mapsi API-dest.','Business search' => 'Ettevõtete otsing','Enable search for businesses in the company field' => 'Luba ettevõtete otsingut ettevõtte väljal','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Luba ettevõttega seotud aadresside soovituste kuvamine ettevõtte väljale kirjutamisel ning täida seejärel automaatselt kõik aadressiväljad, kui soovituste hulgast valitakse välja ettevõte.','Company result types' => 'Ettevõtte tulemuste liigid','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Valige kuni 5 aadressiotsingu tulemuste tüüpi, mida kuvatakse ettevõtte väljade automaatse täitmise funktsioonis. <br>Soovitatav väärtus on <code>ettevõte</code>, mis hõlmab enamikku ettevõtete tüüpe. <br>Jätke väli tühjaks, et aktsepteerida mis tahes tüüpi tulemusi, sealhulgas tulemusi, mis ei ole seotud ettevõtetega. <br>Külasta Google Mapsi dokumentatsiooni, et saada lisateavet <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">toetatud tüüpide</a> kohta.','Google logo' => 'Google\'i logo','Show text and logo "Powered by Google"' => 'Näita teksti ja logo „Powered by Google“','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Kui see valik on märgitud, kuvatakse aadressi automaatse täiendamise soovituste kasti allosas tekst ja logo „Powered by Google“.','Brasil API address autocomplete' => 'Brasil API aadresside automaatne täiendamine','Brasil API' => 'Brasiilia API','Enable Brasil API address autocomplete for CEP fields' => 'Luba CEP-väljade puhul Brasiilia API aadresside automaatne täitmine','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Kasutage Brasil API-d aadresside hankimiseks ja automaatseks täitmiseks, kasutades CEP/postikoodi välja. Kehtib ainult Brasiilia aadresside puhul.','API version' => 'API versioon','Choose which version of the Brasil API CEP method to use.' => 'Valige, millist Brasil API CEP-meetodi versiooni soovite kasutada.','Address book migration' => 'Aadressiraamatu ülekandmine','WooCommerce addresses' => 'WooCommerce’i aadressid','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopeeri olemasolevad tarne- ja arveldusadressid WooCommerce’ist klientide aadressiraamatusse.','Enable the address book feature' => 'Luba aadressiraamatu funktsioon','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Võimaldage klientidel salvestada mitu aadressi ja määrata vaikimisi aadress, mida kasutatakse kauba saatmiseks ja arve esitamiseks.','Address labels' => 'Aadressietiketid','Allow customers to add a custom label for each address' => 'Võimaldage klientidel lisada igale aadressile kohandatud silt','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Aadressisildid aitavad klientidel kergemini eristada oma salvestatud aadresse (nt „Ema maja”). Aadressisildid on klientidele privaatsed ning neid ei kuvata ega trükita tellimuse üksikasjade lehel ega arvetel.','Display layout' => 'Ekraani paigutus','Choose how saved addresses are displayed at checkout and on the cart.' => 'Valige, kuidas salvestatud aadresse kuvatakse kassasse minnes ja ostukorvis.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Kehtib kassas ja ostukorvis. Kontolehel salvestatud aadressid kuvatakse alati kaardipaigutusena.','Address cards' => 'Aadressikaardid','Address list' => 'Aadresside nimekiri','Dropdown field' => 'Rippmenüüväli','Address search' => 'Aadressiotsing','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Näita kasutajaliideses aadressiotsingu filtrit, kui kliendil on salvestatud vähemalt see arv aadresse.','Not used when display layout is set to dropdown field.' => 'Seda ei kasutata, kui kuvamisviisiks on valitud rippmenüü.','Addresses' => 'Aadressid','Enable cart page optimizations to see more options' => 'Luba ostukorvi lehe optimeerimised, et näha rohkem valikuid','Sticky order summary' => 'Kinnitatud tellimuse kokkuvõte','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Valige koht, kus kupongikoodide osa ostukorvi lehel kuvada. Kehtib ainult juhul, kui AJAX-ostukorv on aktiveeritud ja kui kupongikoodide kasutamine on WooCommerce’i seadetes lubatud.','Layout of cross-sell' => 'Ristmüügi ülesehitus','Cross-sells displayed' => 'Kuvatakse seotud tooteid','Items' => 'Kaubad','Cart page optimization' => 'Ostukorvi lehe optimeerimine','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Andke oma ostukorvile sama selge ja müügile suunatud kujundus nagu kassale.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Kohandage ostukorvi kujundus kassalehega, et tagada ühtne ostukogemus.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Hoia ostukorvi sisu taustal alati ajakohasena – koguste muutumisel ei laadita lehte uuesti täielikult.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Paiguta sooduskoodid, saatmiskulud ja täiendavad tooted just sinna, kus need toovad kõige rohkem müüki.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Hoidke tellimuse kokkuvõte kerimise ajal nähtaval ning lisage usaldusmärgid kohtadesse, kus ostjad vajavad kindlustunnet.','Columns' => 'Veerud','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Kassasse mineku etappide, tellimuse kokkuvõtte ja muude osade üldised stiilid. Kehtib ka teiste kassasse mineku, ostukorvi, tänulehe (tellimus on vastu võetud) ja tellimuse vaatamise lehtede puhul.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Kui kasutatakse <em>"1 veerg"</em> paigutust koos <em>"Split"</em> kujundusmalliga, kuvatakse parempoolne veerg ainult juhul, kui lehe külgriba vidinaala on aktiivne (kassasse mineku külgriba, ostukorvi külgriba või tellimuse kättesaamise külgriba). Muul juhul jääb leht üheveeruliseks, kasutades „Split“ stiile.','Split column background' => 'Veeru taust jagatud','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Valige „Split“-kujunduse teise veeru taustavärv. Jätke väli tühjaks, kui soovite kasutada tellimuse kokkuvõtte taustavärvi.','Page templates' => 'Lehekülje mallid','Checkout template' => 'Kassasse mineku mall','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Soovitatav, et vähendada ostukorvi tühjendamisel esinevaid segavaid tegureid. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Loe uuringut ostukorvi hülgamise kohta</a>.','Sticky progress bar' => 'Kinnitatud edenemisriba','Progress bar style' => 'Edusammude riba stiil','Order totals' => 'Tellimuste kogusummad','Background color' => 'Taustavärv','Action link' => 'Tegevuslink','Mobile order summary' => 'Mobiiltellimuse kokkuvõte','Mobile initial state' => 'Mobiilseadme algseisund','Enable editing cart items at checkout' => 'Luba ostukorvi toodete muutmine kassasse jõudmisel','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Võimaldage klientidel muuta toodete koguseid või eemaldada tooteid otse kassaleheküljel.','Cart item errors' => 'Ostukorvi toodete vead','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Kehtib ainult juhul, kui kupongikood on esitatud eraldi osana kassasse mineku või ostukorvi lehel ning kui kupongikoodide kasutamine on WooCommerce’i seadetes lubatud.','Coupon codes position' => 'Kupongikoodide asukoht','Apply coupon button' => 'Kupongi rakendamise nupp','Select style of the "apply coupon" button.' => 'Vali nupu „Kupongi rakenda” stiil.','Address line 2' => 'Aadressirida 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'See seade kehtib nii „Kassasse“ kui ka „Kohapealne kättesaamine“ jaotiste puhul. Jaotises „Kohapealne kättesaamine“ määrab see ka, kas valik „Saadetis/Kättesaamine“ kuvatakse saatmisviisi jaotises (enne aadressi) või eraldi jaotises (pärast seda).','Customer accounts' => 'Kliendikontod','Guest checkout' => 'Külaliskassasse','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce’i kontode seadete lehel asuvad külaliskassasse mineku, sisselogimise ja konto loomise valikud. Neid hallatakse siin teie mugavuse huvides, et saaksite kasutada erinevaid väärtusi iga seadete profiili puhul.','Allow customers to checkout without an account' => 'Võimaldage klientidel teha ostu ilma kontota','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Soovitatav</strong>, et klientidel ei palutaks kassasse minnes kontot luua ega sisse logida, mis võib vähendada konversioonimäärasid.','When disabled, customers must log in or create an account to complete the purchase.' => 'Kui see funktsioon on keelatud, peavad kliendid sisse logima või konto looma, et ostu lõpule viia.','Login at checkout' => 'Logi sisse kassasse minnes','Enable log-in during checkout' => 'Luba sisselogimine ostukorvi tühjendamise ajal','Show a link for returning customers to log in from the checkout page.' => 'Näita kassalehel püsiklientidele linki sisselogimiseks.','Account creation' => 'Konto loomine','Allow customers to create an account during checkout' => 'Võimaldage klientidel kassasse minnes konto luua','Customers can create an account before placing their order.' => 'Kliendid saavad enne tellimuse esitamist luua konto.','Allow customers to create an account from the My account page' => 'Võimaldage klientidel luua konto leheküljel „Minu konto“','Customers can register a new account from the My account page.' => 'Kliendid saavad luua uue konto lehel „Minu konto”.','Username' => 'Kasutajanimi','Generate from customer\'s name' => 'Loo kliendi nime põhjal','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Soovitatav</strong>, et klientidel ei palutaks kassasse minnes kasutajanime valida, mis võib vähendada konversioonimäära.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Kasutajanimi luuakse kliendi nime põhjal või, kui nime kasutada ei ole võimalik, e-posti aadressi põhjal.','Password' => 'Parool','Send password setup link' => 'Saada parooli seadistamise link','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Soovitatav</strong>, et klientidelt ei küsitaks kassasse minnes parooli, mis võib vähendada konversioonimäära.','Customers receive an email to create their password securely.' => 'Kliendid saavad e-kirja, milles palutakse neil luua turvaline parool.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Võimaldage registreeritud klientidel sooritada ostu lõpetamine ilma sisselogimata ning seostage tellimus nende olemasoleva kontoga, kui kontaktandmed ühtivad.','Existing account message' => 'Teade olemasoleva konto kohta','Let customers create an account after placing their order, from the thank you page.' => 'Võimaldage klientidel luua konto pärast tellimuse esitamist tänulehelt.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Selles jaotises olevad valikud on kättesaadavad, kui külaliskassasse minek ja kontode sobitamine on lubatud. Luba mõlemad eespool nimetatud funktsioonid, et seadistada konto loomise edasilükkamine.','Enable delayed account creation' => 'Luba konto loomise edasilükkamine','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Luba konto loomise edasilükkamine, kui nii külaliskassasse minek kui ka kontode sobitamine on lubatud.','Section position' => 'Lõigu asukoht','Before customer details section' => 'Enne kliendi andmete osa','After customer details section' => 'Pärast kliendi andmete osa','Account creation benefits' => 'Konto loomise eelised','Leaving the field empty will display the default text.' => 'Kui väli jäetakse tühjaks, kuvatakse vaikimisi tekst.','Inline buttons' => 'Tekstisisesed nupud','Required fields' => 'Kohustuslikud väljad','Enable gift message fields at checkout' => 'Luba kinkesõnumi väljad kassasse jõudmisel','Expanded gift message' => 'Täiendatud kingituse sõnum','Display gift message field always expanded' => 'Kinkesõnumi väljale jääb alati avatud','Gift message in order details' => 'Kingituse sõnum tellimuse üksikasjades','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Praegu pole selles jaotises ühtegi integratsiooni saadaval. Iga pistikprogrammi ja teemaga seotud valikud kuvatakse siin alles siis, kui vastav pistikprogramm või teema on aktiveeritud.','Phone fields' => 'Telefoni väljad','Field visibility' => 'Välja nähtavus','Field position' => 'Väljakupositsioon','Phone country code & validation' => 'Riigi telefonikood ja selle kontrollimine','Country' => 'Riik','Enable country on phone fields' => 'Luba riigi valik telefoninumbri väljadel','Filter countries for shipping or billing' => 'Filtreeri riike tarne- või arveldusandmete alusel','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Piirata iga telefoninumbri väljal riigi valikut vaid nendele riikidele, kuhu teie poest on lubatud saata kaupa või kuhu on lubatud arveid esitada.','Validation' => 'Valideerimine','Enable simple validation based on country rules' => 'Luba lihtne kehtivuse kontroll riikide eeskirjade alusel','Checks that the phone number is valid for the selected country, including country code and length.' => 'Kontrollib, kas valitud riigi puhul on telefoninumber kehtiv, sealhulgas riigikood ja numbrite pikkus.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Rangem kontroll, et number oleks valitud riigis kehtiv mobiili-, tavatelefoni- või muu aktsepteeritud tüüpi number. Võib tagasi lükata mõned kehtivad numbrid.','Validation types' => 'Valideerimise tüübid','Placeholders' => 'Asendussümbolid','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Hetkel pole hallatavaid litsentsivõtmeid. Litsentsivõtmed kuvatakse siin, kui on aktiivne litsentsitud Fluid Checkouti pistikprogramm või lisand.','Default delivery type' => 'Vaikimisi valitud kohaletoimetamise viis','Choose which delivery type will be selected by default.' => 'Valige, milline kohaletoimetamise viis on vaikimisi valitud.','Shipping zone fields' => 'Saadetiste tsoonide väljad','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Valige, millised väljad kuvatakse kohaliku kättesaamise tarnepiirkonna filtri väljadena. Jätke tühjaks, et kuvada kõik saadaval olevad valikud.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Need väljad kuvatakse kohaliku kättesaamise tarneviiside filtri all. Mõned väljad võivad kassasse jõudes siiski ilmuda, isegi kui neid siin ei ole valitud, kui ühilduvad pistikprogrammid vajavad neid oma nõuetekohaseks toimimiseks.','Order shipping address' => 'Tellimuse tarneadresse','Order pay page optimization' => 'Tellimuse maksmise lehe optimeerimine','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Andke tasumata tellimustele sama selge ja müügile suunatud kujundus nagu kassale.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimeerige maksmisele ootavate tellimuste maksmislehe kujundust.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Kohanda tellimuse tasumise protsessi oma kassasse, et tagada ühtne ostukogemus.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Lisage usaldusmärgid ja tunnused kohtadesse, kus ostjad vajavad enne maksmist kinnitust.','Thank you page optimization' => 'Tänulehe optimeerimine','Make the thank you page and order details clearer for customers after they buy.' => 'Tee klientidele pärast ostu sooritamist tänuleht ja tellimuse üksikasjad selgemaks.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimeerige tänulehte ja tellimuse üksikasju selgema kujundusega.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Näita tellimuse staatuse kulgu, toiminguid, allalaadimisi ja märkmeid seal, kus see on asjakohane.','Customize order details sections on email notifications.' => 'Kohandage e-posti teavituste tellimuse üksikasjade osi.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Lisage usaldusmärgid ja tunnused kohtadesse, kus ostjad vajavad pärast ostu kinnitust.','Email notifications' => 'E-posti teated','Enable thank you page and order details optimizations to see more options' => 'Lülita sisse tänulehe ja tellimuse üksikasjade optimeerimine, et näha rohkem valikuid','Use wide layout on thank you page' => 'Kasuta tänulehel laia paigutust','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Need valikud mõjutavad tänulehte, tellimuse üksikasjade kuvamist kontolehtedel ja e-posti teavitustes.','Save settings' => 'Salvesta seaded','Docs' => 'Dokumendid','Cart' => 'Ostukorv','Thank you' => 'Tänan','Address autocomplete' => 'Aadressi automaatne täiendamine','Trust badges' => 'Usaldusmärgid','You do not have permission to save these settings.' => 'Sul pole õigust neid seadeid salvestada.','Invalid save request.' => 'Salvestusnõue on kehtetu.','Your settings have been saved.' => 'Teie seaded on salvestatud.','Saving...' => 'Salvestatakse...','Settings could not be saved. Please try again.' => 'Seadeid ei õnnestunud salvestada. Palun proovi uuesti.','Dismiss notice' => 'Teate sulgemine','Open settings menu' => 'Ava seadete menüü','Close settings menu' => 'Sulge seadete menüü','Preview' => 'Eelvaade','Expand preview' => 'Ava eelvaade','Collapse preview' => 'Peida eelvaade','Show header and footer' => 'Näita päist ja jalust','Hide header and footer' => 'Pealkirja ja jalus peita','Page preview' => 'Lehekülje eelvaade','Preview viewport' => 'Eelvaatevaateala','Tablet' => 'Tahvelarvuti','Desktop' => 'Töölaua','Preview width' => 'Eelvaate laius','Decrease width' => 'Vähenda laius','Preview width in pixels' => 'Eelvaate laius pikslites','Increase width' => 'Suurenda laius','Preview as' => 'Eelvaade kui','Guest' => 'Külaline','Logged in' => 'Sisse logitud','Preview page' => 'Eelvaate leht','Expand preview for a closer look' => 'Ava eelvaade, et seda lähemalt vaadata','Available with %s.' => 'Saadaval koos %s-ga.','Turn them on' => 'Lülita need sisse','Optimizations for this page are turned off. %s to preview the page.' => 'Selle lehe optimeerimisfunktsioonid on välja lülitatud. %s, et lehte eelvaadata.','%s preview' => '%s eelvaade','Isolated session · nothing is saved' => 'Isolatsioonirežiim · midagi ei salvestata','Usage tracking' => 'Kasutamise jälgimine','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Saada mittesalajasi veebikeskkonna aruandeid, et aidata Fluid Checkoutil ühilduvust parandada. Aruandeid ei saadeta enne, kui see on allpool olevates valikutes sisse lülitatud.','Send usage tracking reports to Fluid Checkout' => 'Saada kasutamisjälgimisaruanded Fluid Checkoutile','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Need aruanded aitavad meil parandada teie veebisaidi ühilduvust ja toetust ning neid saadetakse igal nädalal, kui see funktsioon on sisse lülitatud.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Aruannetes ei sisaldu ühtegi kliendi-, administraatori- ega muud tundlikku andmet.','Basic environment info' => 'Põhiteave keskkonna kohta','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPressi, PHP, WooCommerce’i, teemade ja pistikprogrammide loendi andmed. Need lisatakse alati, kui aruandlus on sisse lülitatud. See aitab meil mõista keskkonda, milles teie veebisait töötab.','Plugin settings' => 'Plugina seaded','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Saadab Fluid Checkouti pistikprogrammi seaded, et aidata kaasa tugipäringute lahendamisel ja aidata meil mõista, kuidas te meie pistikprogramme kasutate.','Coming soon' => 'Peagi saadaval','Sales metrics' => 'Müüginäitajad','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Kuu tellimuste arv ja kogumüük alates Fluid Checkouti paigaldamisele eelnenud aastast kuni tänaseni. See aitab meil aru saada, kas teenite meie pistikprogrammide kasutamisel rohkem tulu. Kliendi- ega kasutajaandmeid ei edastata kunagi.','Utilities' => 'Kommunaalteenused','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Kasuta <code>TomSelect</code> rippmenüü komponente <code>select2</code> asemel','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect on lihtsam rippmenüü komponent, mis on vähem veaprobleemidele altis kui Select2, pakkudes samas sama funktsionaalsust.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Määrab selle pistikprogrammi poolt optimeeritud lehtedel vormiväljade kirjasuuruseks 16px, et vältida automaatset suurendamist, kui väikestel seadmetel vormiväljadega suheldakse.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari ja teised brauserid võivad mobiilseadmetel teksti automaatselt suurendada, et seda oleks kergem lugeda, kui kirjasuurus on väiksem kui 16px.','Enable script processing tracking on the browser console.' => 'Luba skriptide töötlemise jälgimine brauseri konsoolis.','Unminified assets' => 'Minifitseerimata ressursid','Google Maps scripts' => 'Google Mapsi skriptid','Do not remove duplicate Google Maps scripts' => 'Ära eemalda dubleeritud Google Mapsi skripte','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Kui see valik on aktiveeritud, siis Google Mapsi skripte ei eemaldata, mis võib põhjustada vigu ja jõudlusprobleeme. Kasuta seda valikut ainult veaotsingul.','Widget areas' => 'Vidinapiirkonnad','Last step on mobile' => 'Viimane samm mobiilis','Display widgets only at last step on mobile' => 'Näita vidinaid mobiilseadmetel ainult viimases etapis','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Näita ostukorvi usaldusmärgi vidinaid ainult siis, kui mobiilseadmes vaadatakse ostukorvi viimast sammu','Standard' => 'Standard','VAT number field' => 'Käibemaksukohustuslase numbri väli','Add a VAT number field to the billing form.' => 'Lisa arvevormile käibemaksunumbri väli.','Field label' => 'Välja silt','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Määrake käibemaksunumbri välja silt (nt „käibemaksunumber”). Mitmekeelsetel veebisaitidel on parem jätta see väli tühjaks ja tõlkida algne tekst.','VAT Number' => 'käibemaksukohustuslase number','EU-VAT' => 'ELi käibemaks','Enable the VAT number field to see more options' => 'Lülita käibemaksunumbri väli sisse, et näha rohkem valikuid','VAT validation' => 'käibemaksu kinnitamine','Validate VAT number field for EU-VAT during checkout' => 'Kontrolli kassasse minnes ELi käibemaksunumbri välja kehtivust','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Kontrollib, kas esitatud käibemaksukohustuslase number on kehtiv ja registreeritud Euroopa VIES-andmebaasis (käibemaksu teabevahetussüsteem).','Shop VAT number' => 'Kaupluse käibemaksukood','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Kaupluse käibemaksukood, mida kasutatakse ELi käibemaksu kinnituse taotlemiseks ja mis on trükitud arvetele. <br><strong>Soovitame tungivalt lisada oma kaupluse käibemaksukoodi</strong>, kuna vastasel juhul võivad VIES-i päringu tulemused raamatupidamise eesmärgil kehtetuks osutuda. <br>Näiteks: <code>ATU99999999</code> või <code>EE999999999</code>.','Reverse charge' => 'Kohustuse ülekandmine','Apply reverse charge mechanism' => 'Kohaldada pöördmaksustamise korda','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Kui kliendi käibemaksunumber on kehtiv, seadke maksumäär nulliks ja kuvage arvetel tekst „Kohustuse ülekandmine”. Sõltuvalt poe asukohariigist võib olla vaja kasutada teistsugust teksti „Kohustuse ülekandmine”.','Same country' => 'Sama riik','Apply reverse charge mechanism for transactions in the shop country:' => 'Kohaldage pöördmaksustamise korda tehingute suhtes, mis toimuvad poe asukohariigis:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Võimaldab kohaldada pöördmaksustamise korda tehingute puhul, mis toimuvad kaupluse asukohariigis asuvate ettevõtete vahel.','Reverse charge exceptions' => 'Kohustuse ülekandmise erandid','Select additional countries to skip applying the reverse charge mechanism.' => 'Valige täiendavad riigid, mille puhul pöördmaksustamise mehhanismi kohaldamist ei rakendata.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Nendest riikidest pärit tellimustelt võetakse makse ka siis, kui on esitatud kehtiv käibemaksukohustuslase number.','Reverse charge label on invoices' => 'Arvetel olev „pöördmaksustamise“ märge','Set the label of "reverse charge" on the checkout page and order details.' => 'Märgi kassalehel ja tellimuse üksikasjades valik „pöördmaksustamine”.','Reverse charge text on invoices' => 'Arvetel esitatav pöördmaksustamise tekst','Set the label of "reverse charge" text on invoices.' => 'Määrake arvetele teksti „pöördmaksustamine” silt.','Tax to be paid on reverse charge basis' => 'Maks, mis tuleb tasuda pöördmaksustamise korras','Company name' => 'Ettevõtte nimi','Autocomplete company name from VAT number' => 'Ettevõtte nime automaatne täiendamine käibemaksunumbri alusel','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Sisestage arve esitaja nimi vastavalt kliendi esitatud kehtivale käibemaksunumbrile.','Company name editing' => 'Ettevõtte nime muutmine','Allow editing of auto-filled company name' => 'Luba automaatselt täidetud ettevõtte nime muutmist','When enabled, customers can change the company name associated with the provided VAT number.' => 'Kui see funktsioon on aktiveeritud, saavad kliendid muuta esitatud käibemaksunumbriga seotud ettevõtte nime.','EU-VAT for digital goods' => 'Digitaalsete kaupade ELi käibemaks','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Alates 1. jaanuarist 2015 on digitaalsete kaupade suhtes tehtud muudatusi ELi käibemaksueeskirjades, mis mõjutavad ainult B2C-tehinguid. Digitaalsete kaupade käibemaks tuleb arvutada kliendi asukoha alusel ning selle kohta tuleb koguda tõendusmaterjali (IP-aadress ja arveaadress).','Tax classes for digital goods' => 'Digitaalsete kaupade maksuklassid','Select some tax classes' => 'Valige mõned maksuklassid','Location evidence' => 'Asukoha tõendid','Collect customer\'s location evidence' => 'Koguda tõendeid kliendi asukoha kohta','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Salvestab IP-aadressi ja võrdleb seda kliendi arveldusadresseeriga. Kui kliendi arveldusadresseer ja IP-aadress ei lange kokku, peab klient oma arveldusadresseeri kinnitama, märkides selleks kassaleheküljel vastava valikukasti.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Seda valikut hallatakse Fluid Checkoutis. <a href="%s">Muuda seda kliendikontode seadetes</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Seda valikut hallatakse Fluid Checkoutis. Saad seda muuta menüüs „Fluid Checkout > Kliendikontod”.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Seda valikut hallatakse Fluid Checkoutis. Kui Fluid Checkout on aktiveeritud, on saatmiskohaks alati määratud „Vaikimisi kliendi saatmisadresse”. Kliendid saavad kassasse minnes siiski sisestada erinevad tarne- ja arveldusadressid.<br><br>Võimalus määrata vaikimisi arveldusadressiks sama aadress, mis on tarneaadress, on saadaval <a href="%s">Fluid Checkouti seadetes</a>.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Seda valikut hallatakse Fluid Checkoutis. Kui Fluid Checkout on aktiveeritud, on tarne sihtkoht alati seatud valikule „Vaikimisi kliendi tarneaadress“. Kliendid saavad kassasse minnes siiski sisestada erinevad tarne- ja arveldusadressid.<br><br>Võimalus määrata vaikimisi arveldusadressiks sama aadress, mis on tarneaadress, on saadaval menüüs WooCommerce > Seaded > Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Need seaded on viidud menüüsse „WP Admin > Fluid Checkout > Seaded“.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'See WooCommerce’i seadete vahekaart on vananenud ja eemaldatakse versioonis Fluid Checkout 6.0.','Go to settings page' => 'Mine seadete lehele','Hide this tab permanently' => 'Peida see vahekaart lõplikult','Site report preview' => 'Veebilehe aruande eelvaade','This is the data that would be included in the next site environment report based on your current settings.' => 'Need on andmed, mis lisataks järgmisesse veebikeskkonna aruandesse teie praeguste seadistuste põhjal.','Loading report preview...' => 'Aruande eelvaate laadimine...','Could not load the site report preview. Try again.' => 'Veebilehe aruande eelvaadet ei õnnestunud laadida. Proovi uuesti.','Could not send the site report. Try again.' => 'Veebisaidi aruannet ei õnnestunud saata. Proovi uuesti.','Site report sent successfully.' => 'Veebisaidi aruanne saadeti edukalt ära.','Enable and send now' => 'Luba ja saada kohe','Close' => 'Sulge','A site report request is already in progress. Try again in a moment.' => 'Kohapealse aruande taotlus on juba menetluses. Palun proovi veidi aja pärast uuesti.','Site environment reporting is disabled.' => 'Veebisaidi keskkonnaaruandlus on välja lülitatud.','No site report data is available to send.' => 'Saada pole ühtegi asukoha aruande andmeid.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Sellelt veebisaidi domeenilt ei saa saata keskkonnaaruandeid (välja arvatud kohalikud või arendusdomeenid).','A site report was sent recently. Try again later.' => 'Hiljuti saadeti kohapealne aruanne. Proovi hiljem uuesti.','The site report could not be sent. Try again later.' => 'Veebilehe aruannet ei õnnestunud saata. Proovi hiljem uuesti.','Site environment reporting is not available.' => 'Asukoha keskkonnaalaseid aruandeid ei ole kättesaadavad.','No site report data is available for the selected settings.' => 'Valitud seadete puhul ei ole saadaval ühtegi vaatluskohtade aruande andmeid.','You are not allowed to manage site reports.' => 'Teil ei ole õigust hallata veebisaidi aruandeid.','PRO feature' => 'PRO-funktsioon','Other plugins' => 'Muud pistikprogrammid','Get only this add-on &mdash; %s' => 'Hangi ainult see lisand — %s','Install add-on' => 'Paigalda lisand','Upgrade to PRO &mdash; %s' => 'Uuenda PRO-versioonile &mdash; %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Hangi %2$s</a>, et need valikud avada.','Add-on' => 'Lisandmoodul','View documentation' => 'Vaata dokumentatsiooni','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Päringute tegemiseks peab WordPressi kasutaja olema sisse logitud. Jäta user_id välja, et kasutada praeguse kasutaja andmeid, või edasta user_id, et suunata päring teisele kontole, kui päringu tegija saab seda kasutajat muuta (õigus edit_user). Autentimata päringud tagastavad vea fc_api_forbidden. Kehtetu user_id tagastab vea fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 koos { "data": { ... } }, kui käitleja tagastab andmepaketi.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 koos { "success": true }, kui andmeid ei ole (näiteks DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Vigade korral tagastatakse WordPressi REST-viga JSON-vormingus WP_Error-i kaudu (kood, sõnum, data.status). Wire-koodides kasutatakse eesliidet fc_api_*.','Forbidden access.' => 'Juurdepääs keelatud.','Target user was not found.' => 'Sihtkasutajat ei leitud.','This feature is not available.' => 'See funktsioon ei ole saadaval.','A required address field is missing.' => 'Puudub kohustuslik aadressiväli.','Postcode or ZIP is invalid.' => 'Postikood või ZIP-kood on kehtetu.','Phone number is invalid.' => 'Telefoninumber on kehtetu.','State or county is invalid.' => 'Osariik või maakond on kehtetu.','Country is invalid or has no address fields.' => 'Riik on kehtetu või sellel puuduvad aadressiväljad.','The request could not be processed.' => 'Päringut ei õnnestunud töödelda.','Back to previous step' => 'Tagasi eelmisele sammile','Skip to settings' => 'Mine otse seadistustesse','Start over and return to the first guided setup step' => 'Alusta uuesti ja naase esimese juhendatud seadistamise sammu juurde','Start over' => 'Alusta uuesti','Please complete all sub-steps before continuing.' => 'Palun viige kõik alametapid lõpule, enne kui jätkate.','Expand' => 'Laadi lahti','Collapse' => 'Kokku klappida','Skip' => 'Vahelejätmine','Mark as complete' => 'Märgi lõpetatuks','Mark as incomplete' => 'Märgi lõpetamata','View full-size image: %s' => 'Vaata pilti täissuuruses: %s','Full-size setup guide image' => 'Täissuuruses seadistamisjuhendi pilt','Close image' => 'Sulge pilt','Fluid Checkout Guided Setup' => 'Fluid Checkouti juhendatud seadistamine','Welcome' => 'Tere tulemast','Explore your checkout' => 'Tutvu oma ostukorviga','All set' => 'Kõik on valmis','You do not have permission to access this page.' => 'Teil puudub juurdepääsuõigus sellele lehele.','Go to step %1$d: %2$s' => 'Mine sammu %1$d juurde: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'See juhendatud seadistamine aitab teil Fluid Checkoutiga tutvuda. Allpool toodud sammud on praegu vaid paigahoidjad.','Continue to the next step when you are ready.' => 'Kui olete valmis, jätkake järgmise sammuga.','Open your store checkout to see Fluid Checkout in action.' => 'Ava oma poe kassaleht, et näha Fluid Checkouti töös.','View checkout page' => 'Vaata kassalehekülge','You can return to Fluid Checkout settings to continue configuring your store.' => 'Võite naasta Fluid Checkouti seadistuste juurde, et jätkata oma poe konfigureerimist.','Review checkout and cart settings' => 'Vaata kassasse mineku ja ostukorvi seadeid','Explore add-ons from the dashboard' => 'Tutvu lisandmodulitega juhtpaneelist','Finish & go to settings' => 'Lõpeta ja mine seadistustesse','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Muuda arveldustelefoni välja nähtavuse seadet, et see vastaks WooCommerce’i tavadele.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Muuda saadetise telefoninumbri välja nähtavuse seadet, et see vastaks WooCommerce’i tavadele.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopeeri tellimuse kokkuvõtte taustavärvi seade uue „Split design” teise veeru taustavärvi valikule.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Biteshipi pistikprogrammi kasutamisel on täiustatud valikuväljade funktsioon alati välja lülitatud.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Saksa turu kasutamisel on tellimuse esitamise asukoht alati seatud valikule „Tellimuse kokkuvõtte all”. See pistikprogramm nõuab, et tellimuse esitamise nupp ja õiguslikud valikukastid kuvataks tellimuse kokkuvõtte all.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Plugin „Germanized for WooCommerce“ kasutamisel on tellimuse esitamise asukoht alati seatud valikule „Tellimuse kokkuvõtte all“. See plugin nõuab, et tellimuse esitamise nupp ja õiguslikud valikukastid kuvataks tellimuse kokkuvõtte all.','Edit pickup locations' => 'Muuda kättesaamiskohti','Use local pickup label from WooCommerce settings' => 'Kasuta WooCommerce’i seadistustest pärit kohaliku kättesaamise sildit','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Kui see on sisse lülitatud, vastab kassas kuvatav isikliku kättesaamise valiku silt pealkirjale, mis on määratud WooCommerce’i isikliku kättesaamise asukoha seadetes. Kui see on välja lülitatud, kasutatakse sildil Fluid Checkout’ist pärit tõlgitavat teksti „Isiklik kättesaamine”.','Button label for applying coupon codesApply' => 'Rakenda','Checkout step titleContact' => 'Kontakt','Checkout step titleShipping' => 'Laevandus','Checkout step titleBilling' => 'Arveldamine','Checkout step titlePayment' => 'Maksmine','Checkout substep change link labelChange' => 'Muuda','Checkout substep save link labelSave changes' => 'Muudatuste salvestamine','Substep review textNone.' => 'Ei ole.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No 